export async function effectiveHermesSelection(stateDir,cached){let value;try{value=await json(path.join(stateDir,'hermes-scoped.json'),8192);}catch(e){if(e.code==='ENOENT')assert.fail('PERSONAL_NEW_ADDRESS_NOT_SAVED');throw e;}
 assert(value?.version===2&&Object.keys(value).sort().join()==='configuration,previousConfiguration,version'&&sameConfiguration(value.previousConfiguration,cached)&&sameConfiguration({...value.previousConfiguration,apiUrl:value.configuration?.apiUrl,daemonOrigin:value.configuration?.daemonOrigin},value.configuration)&&value.configuration.apiUrl===value.configuration.daemonOrigin,'PERSONAL_NEW_ADDRESS_NOT_SAVED');return value.configuration;}

