async announceHumanDecision({nextFlow,outcome}){const caseId=this.plan.flowCases[nextFlow];await this.ownerInstructions.post({id:`decision-${nextFlow}`,kind:'human-decision',caseId,outcome,
   text:`In the staging website, personally ${outcome==='declined'?'Decline':'Approve once'} the pending request for ${caseId}. `+
    `${outcome==='declined'?'Leave every other pending request untouched until you are asked. ':''}Do not send another task.`});}
// The server claims a role's oldest delivered/acknowledged work first (deliveredAt||createdAt, then id) across all cases;
// order same-role single flows by that key from the role's own inbox copies.
async claimOrder(role,effects){this.live();const rows=[];for(const e of effects){const s=await this.snapshot(role,e.caseId,`claim-order-${role}`),copies=s.record.messages.filter(m=>m.id===e.id&&m.recipientAgentId===this.actors[role].agentId);
 assert.equal(copies.length,1,'ONE_EXACT_QUEUED_COPY_REQUIRED');assert(['delivered','acknowledged'].includes(copies[0].status),'QUEUED_WORK_REQUIRED');rows.push({e,key:String(copies[0].deliveredAt||copies[0].createdAt),id:String(copies[0].id)});}
 return rows.sort((a,b)=>a.key.localeCompare(b.key)||a.id.localeCompare(b.id)).map(r=>r.e);}
async pauseFor(ms){assert(Number.isSafeInteger(ms)&&ms>0);const until=Date.now()+ms;assert(until<Date.parse(this.controller.receipt.hardStopUtc),'WAIT_CANNOT_FIT_FIXED_WINDOW');while(Date.now()<until){this.live();await delay(Math.min(250,until-Date.now()),undefined,{signal:this.controller.control.signal});}}

