const greenProposal=await c.effect('oc-canary-no-action',{recipientRole:'testowner',type:'proposal'}),fileProposal=await c.effect('oc-shared-read-propose',{recipientRole:'testowner',type:'proposal'});
// Both proposals are queued for Testowner and the server serves the older first, so run their flows in that order.
let actualFixture;for(const proposal of await c.claimOrder('testowner',[greenProposal,fileProposal])){
 if(proposal.id===greenProposal.id){await one(await incoming('accept-authority',{parentEffect:greenProposal}));
  // Original request_human turn has ALREADY ended/settled. Owner decline must precede real expiry; a NEW actual decision scope is probed.
  actualFixture=await fixture.current();assert(actualFixture?.operator&&actualFixture?.hooks,'ACTUAL_BOUND_C08_FIXTURE_REQUIRED');
  await actualFixture.operator.observeNativeHumanAndOriginalEnd();await c.announceHumanDecision({nextFlow:'declined-resume',outcome:'declined'});}
 else await one(await incoming('asset-decline',{parentEffect:fileProposal}));}
// Both proposals are processed, so the personal decline is Testowner's oldest queued work. Approval is requested only after declined-resume.
const declined=await c.waitHumanDecision({authorityFlow:'accept-authority',nextFlow:'declined-resume',outcome:'declined'});
await actualFixture.hooks.runAndCaptureControl({controlId:c.plan.controls.testowner.authorityExpiry,mode:'authority-expiry',role:'testowner',caseId:declined.caseId,workId:declined.workId,evidenceSha256:declined.evidenceSha256});
// The control ends with the SDK's retryable HANDLER_FAILED on the decision's first claim: server retryAt = 5000ms*2^(1-1)
// (staging default; the hosted guard pins the Worker bindings, which set no override). Claim only after it.
await c.pauseFor(7000);
await one(await incoming('declined-resume',{workId:declined.workId,kind:'humanDecision',outcome:'declined'}));

