export function terminalResponses(bytes){
 const text=Buffer.from(bytes).toString('utf8');let value;try{value=JSON.parse(text);}catch{const events=text.split(/\r?\n/).filter(line=>line.startsWith('data:')).map(line=>line.slice(5).trim()).filter(line=>line&&line!=='[DONE]').map(line=>JSON.parse(line));
  assert(!events.some(e=>['response.failed','response.incomplete'].includes(e.type)),'NATIVE_RESPONSE_FAILED');value=events.filter(e=>e.type==='response.completed').at(-1)?.response;}
 assert(value&&value.status==='completed'&&Array.isArray(value.output),'ACTUAL_TERMINAL_RESPONSE_REQUIRED');
 assert(!value.output.some(item=>item.type==='function_call'),'NATIVE_TOOL_CONTINUATION_PENDING');return value;
}
export function verifyNoActionCanonicalChange(before,after,workId,settlement){
 assert.deepEqual([...before.ids].sort(),[...after.ids].sort(),'NO_ACTION_NEW_OR_REMOVED_MESSAGE');
 const b=before.record.messages.find(m=>m.id===workId),a=after.record.messages.find(m=>m.id===workId);assert(b&&a);
 assert.equal(a.status,'processed');assert.equal(a.processedAt,settlement.receipt.createdAt);assert.equal(a.updatedAt,a.processedAt);
 assert(Date.parse(a.processedAt)>=Date.parse(b.updatedAt||b.deliveredAt||b.createdAt));
 if(b.acknowledgedAt!==undefined)assert.equal(a.acknowledgedAt,b.acknowledgedAt);
 if(a.acknowledgedAt!==undefined)assert(Date.parse(a.acknowledgedAt)<=Date.parse(a.processedAt));
 const strip=m=>Object.fromEntries(Object.entries(m).filter(([k])=>!['status','processedAt','updatedAt','acknowledgedAt'].includes(k)));
 assert.equal(digest(strip(b)),digest(strip(a)),'NO_ACTION_MESSAGE_BODY_CHANGED');
 assert.equal(JSON.stringify(before.record.messages.filter(m=>m.id!==workId)),JSON.stringify(after.record.messages.filter(m=>m.id!==workId)),'NO_ACTION_FOREIGN_MESSAGE_CHANGED');
 if(b.kind==='humanDecision')assert.equal(digest(before.record.case),digest(after.record.case),'NO_ACTION_CASE_CHANGED');
 else{const normalized=structuredClone(after.record.case),oldEvent=before.record.case.events.find(e=>e.id===`evt_${workId}`),event=normalized.events.find(e=>e.id===`evt_${workId}`);
  assert(oldEvent&&event&&event.payload.messageId===workId,'EXACT_RECEIVING_DELIVERY_EVENT_REQUIRED');
  assert.equal(event.payload.deliveryState,'processed');assert.equal(normalized.updatedAt,settlement.receipt.createdAt);
  event.payload.deliveryState=oldEvent.payload.deliveryState;normalized.updatedAt=before.record.case.updatedAt;
  assert.equal(digest(normalized),digest(before.record.case),'NO_ACTION_CASE_CHANGED_OUTSIDE_DELIVERY_LIFECYCLE');}
}
